package spms.components;
import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;
public final class StatusBadge extends JLabel {public StatusBadge(String value,boolean selected){super(value,SwingConstants.CENTER);setOpaque(true);setBorder(new EmptyBorder(4,8,4,8));if(selected){setBackground(new Color(222,243,242));setForeground(new Color(31,48,66));}else if(value.equals("APPROVED")||value.equals("PRESENT")||value.equals("PAID")||value.equals("ACTIVE")){setBackground(new Color(228,245,238));setForeground(new Color(24,125,100));}else if(value.equals("PENDING")||value.equals("DRAFT")||value.equals("PROCESSED")){setBackground(new Color(252,243,221));setForeground(new Color(151,97,20));}else if(value.equals("REJECTED")||value.equals("ABSENT")||value.equals("INACTIVE")){setBackground(new Color(250,232,232));setForeground(new Color(174,65,65));}else{setBackground(Color.WHITE);setForeground(new Color(31,48,66));}}}
